"""Build static, progressively enhanced pages from the checked-in resource manifest."""
import json,re,html
from pathlib import Path
R=Path(__file__).resolve().parents[1]; resources=json.loads((R/'data/resources.json').read_text()); esc=html.escape
BOOK='https://quarcs-lab.github.io/macro102-site/'
byid={r['id']:r for r in resources}
nav=[('Home','index.html'),('Book',BOOK),('AI Podcasts','podcasts.html'),('AI Tutors','tutors.html'),('Data Apps','data-apps.html'),('Figure Apps','figure-apps.html')]
def page(name,title,description,body):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==name else '')+f'>{label}</a>' for label,url in nav)
 s=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Data Science &amp; Macroeconomics</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#0b1425"><meta property="og:title" content="{esc(title)} — Data Science &amp; Macroeconomics"><meta property="og:description" content="{esc(description)}"><meta property="og:image" content="https://quarcs-lab.github.io/macro102-hub/assets/economic-world.jpg"><meta property="og:type" content="website"><link rel="canonical" href="https://quarcs-lab.github.io/macro102-hub/{'' if name=='index.html' else name}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><script src="assets/theme.js"></script><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;450;500;550;600;650;700;750;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="nav-shell"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">m<span>↗</span></span><span>Data Science <span class="brand-second">&amp; Macroeconomics</span></span></a><nav id="navigation" aria-label="Main navigation">{links}</nav><button class="icon-button" id="theme-toggle" aria-label="Switch to light theme" title="Switch theme">☼</button><button class="menu-button" aria-controls="navigation" aria-expanded="false">Menu</button></div></header><main id="main">{body}</main><footer><div class="shell footer-inner"><div><a class="brand" href="index.html">Data Science &amp; Macroeconomics</a><p>A Python Companion to Intermediate Macroeconomics.</p><p>By <a href="https://carlos-mendez.org/">Carlos Mendez</a> · <a href="{BOOK}">Read the book ↗</a></p></div><div class="footer-meta"><a href="https://github.com/quarcs-lab/macro102-hub">Source on GitHub ↗</a><a href="https://github.com/quarcs-lab/macro102-hub/issues">Report an issue ↗</a><p>© 2026 Carlos Mendez · <a href="https://creativecommons.org/licenses/by-nc/4.0/">CC BY-NC 4.0</a></p></div></div><div class="shell credit">Companion to Charles I. Jones, <em>Macroeconomics</em> (6th ed., 2024). Independent educational project; not affiliated with the author or publisher. Original website illustration generated with AI.</div></footer></body></html>'''
 (R/name).write_text(s)
def intro(kicker,title,desc): return f'<section class="page-intro shell"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def searchbox(label): return f'<div class="filter-bar"><label>Search {label}<input type="search" id="resource-search" placeholder="Try growth, inflation, or Chapter 7…"></label><label>Topic<select id="topic-filter"><option value="">All topics</option>'+''.join(f'<option>{esc(g)}</option>' for g in dict.fromkeys(r['group'] for r in resources))+'</select></label><p id="result-count" role="status"></p></div>'
slides=[
('growth','Long-run growth','Why are some countries<br>so much richer?','Start with the differences in living standards. Then ask what capital, ideas, and institutions can explain.','ch03','Data · Maddison Project · 1950–2022','GDP per person for the United States, Japan, China, and India from 1950 to 2022.'),
('recessions','Business cycles','Why do economies<br>fall into recession?','Follow output through financial crises and the pandemic. See how far an economy can move from its potential.','ch10','Data · U.S. output gap · BEA / CBO via FRED','U.S. output relative to potential, including the financial crisis and pandemic.'),
('inflation','Prices & purchasing power','What drives<br>inflation?','Trace the history of rising prices, then connect money, expectations, and policy to the inflation rate.','ch08','Data · U.S. CPI inflation · FRED','Annual U.S. consumer price inflation from 1960 through 2025.'),
('employment','The labor market','Why does<br>unemployment persist?','Even in a growing economy, jobs are created and lost. A simple flow model explains a persistent natural rate.','ch07','Model · Job separation 1% · job finding 20% / month','Unemployment converges from 10 percent to a natural rate of 4.76 percent over 24 months.'),
('policy','Stabilization policy','How can policy<br>stabilize the economy?','Bring inflation and output into one diagram. Explore the trade-offs facing central banks after a shock.','ch13','Model · AS/AD · book baseline parameters','Aggregate supply and demand intersect at a zero output gap and 2 percent inflation.'),
('global','The global economy','How do trade and exchange<br>rates connect economies?','Follow prices and interest rates across borders. Explore how international connections reshape domestic choices.','ch20','Model · Uncovered interest parity · one-year horizon','The exchange rate rises with the domestic interest rate, holding foreign interest and expected exchange rates fixed.')]
slide_html=''
for i,(id,topic,q,desc,ch,source,alt) in enumerate(slides):
 slide_html+=f'<article class="question-slide" data-slide="{i}" aria-label="{i+1} of 6: {topic}"'+(' hidden' if i else '')+f'><div class="slide-intro"><p class="eyebrow">{topic}</p><h2>{q}</h2></div><img class="chart" src="assets/charts/{id}.svg" alt="{alt}" width="640" height="360"><div class="slide-caption"><p>{desc}</p><div class="chart-meta">{source}</div><a href="{byid[ch]["book"]}">Explore Chapter {int(ch[2:])} <span aria-hidden="true">↗</span></a></div></article>'
hero=f'''<section class="hero"><div class="shell hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> DATA. MODELS. UNDERSTANDING.</p><h1>Data Science<br><span>&amp; Macroeconomics.</span></h1><p class="hero-hook">Big questions.<br>Evidence you can explore.</p><p class="hero-description">A Python Companion to Intermediate Macroeconomics. Bring economic data to life, put models to work, and connect the two—with code you can run and change.</p><div class="actions"><a class="button primary" href="{BOOK}">Read the book <span>↗</span></a><a class="text-link" href="data-apps.html">Explore the apps <span>→</span></a></div><div class="hero-facts"><span><b>21</b> chapters</span><span><b>9</b> appendices</span><span><b>Python</b> + AI</span></div><div class="hero-art"><img src="assets/economic-world.jpg" alt="An illustrated economy: cities, industry, and a port connected by streams of data beneath a globe." width="1536" height="1024" fetchpriority="high"><span>THE ECONOMY, CONNECTED.</span></div></div><div class="question-deck" role="region" aria-roledescription="carousel" aria-label="Six big questions in macroeconomics"><div class="deck-header"><span>THE QUESTIONS THAT MATTER</span><span id="slide-count">01 / 06</span></div><div class="slides">{slide_html}</div><div class="carousel-controls"><div class="dots">{''.join(f'<button class="dot" data-go="{i}" aria-label="Show question {i+1}: {s[1]}" aria-pressed="{str(i==0).lower()}"></button>' for i,s in enumerate(slides))}</div><div class="transport"><button id="previous-slide" aria-label="Previous question">←</button><button id="pause-slides" aria-label="Pause automatic rotation" aria-pressed="false">Ⅱ</button><button id="next-slide" aria-label="Next question">→</button></div></div></div></div><div class="shell hero-bottom"><span>A COMPANION FOR CURIOUS ECONOMISTS</span><a href="#pathways">Find your starting point ↓</a></div></section>'''
pillars='''<section class="section shell"><div class="section-heading"><p class="eyebrow">FROM QUESTIONS TO UNDERSTANDING</p><h2>Find the facts.<br>Build the explanation.</h2><p>One book brings together three ways of working.<br>Explore an idea, test it, and make it your own.</p></div><div class="pillars"><article><span class="large-number">01</span><h3>Let the data speak.</h3><p>Compare countries, trace long-run changes, and examine turning points. Make the stylized facts visible before choosing an explanation.</p><a href="data-apps.html">Explore Data Apps ↗</a></article><article><span class="large-number">02</span><h3>Put models to work.</h3><p>Change a parameter. Follow the mechanism. Use interactive diagrams to see what a model predicts—and where its assumptions matter.</p><a href="figure-apps.html">Explore Figure Apps ↗</a></article><article><span class="large-number">03</span><h3>Learn by doing.</h3><p>Run the Python notebooks in Google Colab. Listen to chapter discussions, follow the transcript, and bring the material into your teaching.</p><a href="podcasts.html">Listen to AI Podcasts ↗</a></article></div></section>'''
paths=[('01','Growth & living standards','Capital, technology, ideas, and the deep roots of income differences.','ch03','Chapters 3–6 · Appendices D–G'),('02','Work, prices & fluctuations','Employment and inflation, recessions and recovery, and policy responses.','ch07','Chapters 7–15 · Appendices H–I'),('03','Decisions in a connected world','Consumption, investment, public budgets, trade, and exchange rates.','ch16','Chapters 16–20')]
pathways='<section class="pathways section" id="pathways"><div class="shell"><div class="section-heading"><p class="eyebrow">CHOOSE A PATH THROUGH THE BOOK</p><h2>Start with what<br>you want to understand.</h2></div><div class="path-list">'+''.join(f'<a class="path" href="{byid[ch]["book"]}"><span class="path-number">{num}</span><div><p class="eyebrow">{label}</p><h3>{title}</h3><p>{desc}</p></div><span class="path-arrow">↗</span></a>' for num,title,desc,ch,label in paths)+'</div></div></section>'
directory='<section class="section shell" id="chapters"><div class="section-heading"><p class="eyebrow">THE COMPLETE COMPANION</p><h2>A chapter for every question.</h2><p>Read online or open an editable Python notebook.<br>Nothing to install.</p></div>'+searchbox('the book')+'<div class="directory">'
for r in resources:
 directory+=f'<article class="directory-row resource" data-topic="{esc(r["group"])}" data-search="{esc(r["label"]+" "+r["title"]+" "+r["group"])}"><span class="chapter-label">{r["label"]}</span><a class="chapter-title" href="{r["book"]}">{esc(r["title"])}</a><div class="row-links"><a href="{r["book"]}" aria-label="Read {esc(r["title"])}">Read ↗</a><a href="{r["colab"]}" aria-label="Open {esc(r["title"])} in Colab">Colab ↗</a></div></article>'
directory+='</div><p class="empty" hidden>No matching chapters. Try another search or topic.</p></section>'
page('index.html','Explore the book','Explore macroeconomics through real data, interactive models, Python notebooks, and AI podcasts. A companion by Carlos Mendez.',hero+pillars+pathways+directory)
for kind,name,title,desc in [('data','data-apps.html','The facts, at your fingertips.','Explore the book’s data without starting from a blank notebook. Open a chapter’s collection to compare economies, inspect trends, and ask your own questions.'),('model','figure-apps.html','Make the mechanism visible.','Explore the book’s interactive model figures. Change assumptions and parameters to see how the economy responds. These collections are called Model Apps in the book.')]:
 cards=''
 for r in resources:
  if kind not in r['apps']:continue
  app=r['apps'][kind]; topics=[re.sub(r'^(?:Fig\. \d+:|\d+\.\d+)\s*','',t) for t in app['topics']];summary=' · '.join(topics[:3])
  preview=f'<img src="{r["preview"]}" alt="{esc(r["title"])} chapter overview" loading="lazy" width="600" height="340">' if r['preview'] else ''
  cards+=f'<article class="app-card resource" data-topic="{r["group"]}" data-search="{esc(r["label"]+" "+r["title"]+" "+summary)}"><a class="card-image" href="{app["url"]}" tabindex="-1" aria-hidden="true">{preview}<span>CHAPTER OVERVIEW</span></a><div class="card-body"><p class="eyebrow">{r["label"]} · {r["group"]}</p><h2><a href="{app["url"]}">{esc(r["title"])}</a></h2><p>{esc(summary)}</p><div class="card-actions"><a href="{app["url"]}">Open {"Data" if kind=="data" else "Figure"} Apps ↗</a><a href="{r["book"]}">Read chapter</a></div></div></article>'
 body=intro('DATA APPS' if kind=='data' else 'FIGURE APPS',title,desc)+'<section class="shell catalog-section">'+searchbox('apps')+f'<div class="app-grid">{cards}</div><p class="empty" hidden>No matching apps. Try another search or topic.</p></section>'
 page(name,'Data Apps' if kind=='data' else 'Figure Apps',desc,body)
widgets=(R/'audio-player/players.html').read_text();chunks=re.split(r'(?=<div class="podcast-widget" id=)',widgets)[1:]
body=intro('LISTEN. QUESTION. CONNECT.','Macroeconomics,<br>in conversation.','Twenty-one AI-generated chapter discussions. Jump to a section, read along as you listen, or take an episode with you on Spotify.')+'<section class="shell catalog-section">'+searchbox('episodes')+'<div class="episodes"><link rel="stylesheet" href="audio-player/podcast-player.css"><script src="audio-player/podcast-player.js" defer></script>'
for r,chunk in zip([r for r in resources if 'podcast' in r],chunks):
 minutes=round(r['podcast']['duration']/60)
 body+=f'<article class="episode resource" data-topic="{r["group"]}" data-search="{esc(r["label"]+" "+r["title"])}"><div class="episode-summary"><span class="episode-number">{r["id"][2:]}</span><div><p class="eyebrow">{r["group"]} · {minutes} MIN</p><h2>{esc(r["title"])}</h2><a href="{r["book"]}">Read chapter ↗</a></div></div>{chunk}</article>'
body+='</div><p class="empty" hidden>No matching episodes. Try another search or topic.</p><p class="resource-note">AI-generated discussions accompany the book. Check explanations against the chapter and its sources. Transcript timing is approximate.</p></section>'
page('podcasts.html','AI Podcasts','Listen to all 21 macroeconomics chapters with timed transcripts, section navigation, and Spotify links.',body)
body=intro('AI TUTORS · FORTHCOMING','A thinking partner.<br>For your next question.','A dedicated space for AI tutors that accompany the book. This collection is forthcoming.')+f'''<section class="shell tutor-section"><div class="tutor-panel"><div class="tutor-art" aria-hidden="true"><span>?</span><i>Y</i><b>π</b><em>g</em></div><div><span class="coming-badge">IN DEVELOPMENT</span><h2>More ways to work<br>through an idea.</h2><p>The tutors will appear here when they are available. In the meantime, start with the book’s explanations, explore its interactive figures, or listen to a chapter discussion.</p><div class="actions"><a class="button primary" href="{BOOK}">Read the book ↗</a><a class="text-link" href="figure-apps.html">Explore Figure Apps →</a></div></div></div></section>'''
page('tutors.html','AI Tutors — Forthcoming','AI tutors for Data Science & Macroeconomics are forthcoming. Explore the book and its existing resources today.',body)
print('Built five static pages.')
